import wasmUrl from './generated/contract.wasm?url';
import type { BoundResult, PresentationSpec, PresentationIssue } from './types';

interface ContractExports extends WebAssembly.Exports {
 memory: WebAssembly.Memory;
 allocate(size:number):number;
 release(pointer:number,size:number):void;
 validate(pointer:number,size:number):bigint;
}
// Electron's static app uses the packaged asset; SSR/check tooling reads the
// same generated bytes locally. The validator itself has no imports/authority.
let loadingError = '';
const module = await (async () => {
 const bytes = import.meta.env.SSR
  ? await (await import('node:fs/promises')).readFile('src/lib/presentation/generated/contract.wasm')
  : await (await fetch(wasmUrl)).arrayBuffer();
 return (await WebAssembly.instantiate(bytes, {})).instance.exports as ContractExports;
})().catch((cause: unknown) => { loadingError = cause instanceof Error ? cause.message : String(cause); return null; });
const encode=new TextEncoder(), decode=new TextDecoder();
export interface ContractResult {valid:boolean;spec:PresentationSpec|null;issues:PresentationIssue[];resultIds:string[];contractHash?:string}
export function acceptContract(spec:unknown,results:BoundResult[]=[],mode:'full'|'structure'='full',chartsEnabled=true):ContractResult {
 if (!module) return {valid:false,spec:null,issues:[{path:'contract',message:`The shared presentation validator could not load: ${loadingError}`}],resultIds:[]};
 const payload=encode.encode(JSON.stringify({spec,results,mode,charts_enabled:chartsEnabled}));
 const pointer=module.allocate(payload.length);
 let output=0, length=0;
 try {
  new Uint8Array(module.memory.buffer,pointer,payload.length).set(payload);
  const handle=module.validate(pointer,payload.length);
  output=Number(handle & 0xffffffffn);length=Number(handle>>32n);
  return JSON.parse(decode.decode(new Uint8Array(module.memory.buffer,output,length))) as ContractResult;
 } finally {module.release(pointer,payload.length);if(output)module.release(output,length);}
}
